#!/usr/bin/env node
// The SauceScript declarations an editor loads for a program file (`*.sauce.ts`), written into
// `dist/sauce-script/`, the package's `./sauce-script` types export:
//
//   index.d.ts     generated by `src/sauce-script/declarations.ts` from the SDK's registries: the
//                  chains, the defines, every JSON ABI the SDK serves;
//   builtins.d.ts  the language — types, builtins, value methods, `@sauce/token` — copied from the
//                  hand-written `sdk/sauce-script/builtins.d.ts`;
//   ts-plugin.cjs  the TypeScript plugin that drops what TypeScript reports on valid SauceScript,
//                  copied from `sdk/sauce-script/ts-plugin.cjs`.
//
// It reads the BUILT SDK (`dist/`), so it runs after `tsc` in `build`. Nothing here is committed.
import { copyFileSync, mkdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const SDK = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(SDK, "dist", "sauce-script");

const { sauceScriptDeclarations } = await import(pathToFileURL(join(OUT, "declarations.js")).href);
mkdirSync(OUT, { recursive: true });
copyFileSync(join(SDK, "sauce-script", "builtins.d.ts"), join(OUT, "builtins.d.ts"));
copyFileSync(join(SDK, "sauce-script", "ts-plugin.cjs"), join(OUT, "ts-plugin.cjs"));
writeFileSync(join(OUT, "index.d.ts"), sauceScriptDeclarations());
console.log(
  "gen-sauce-script-types: wrote dist/sauce-script/{index,builtins}.d.ts and ts-plugin.cjs",
);
